import random
import math
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_k_cnf(n):
        clauses = []
        for _ in range(2**n):
            clause = [random.choice([1, -1]) * (i + 1) for i in range(n)]
            if all(c == 0 for c in clause):
                continue
            clauses.append(clause)
        return clauses

    def ac0_circuit_size(clauses):
        # Simplified DPLL solver to estimate circuit size
        n = len(clauses[0])
        stack = []
        assignment = [None] * (n + 1)

        def dpll():
            if not stack:
                return True
            literal = stack.pop()
            var, sign = abs(literal), literal > 0
            for i in range(len(clauses)):
                if any(abs(c) == var for c in clauses[i]):
                    if sign != (c < 0):
                        continue
                    else:
                        assignment[var] = sign
                        if dpll():
                            return True
                        assignment[var] = None
                        stack.append(-literal)
            return False

        return len(clauses) + sum(1 for _ in range(n) if assignment[_] is not None)

    def delone_triangulation_size(clauses):
        # Simplified Delone triangulation size estimation
        n = len(clauses[0])
        return 2 * n + len(clauses)

    n = random.randint(5, 40)
    clauses = generate_k_cnf(n)
    ac0_size = ac0_circuit_size(clauses)
    delone_rank = delone_triangulation_size(clauses)

    metric_value = delone_rank / ac0_size
    conjecture_holds = metric_value <= n**2  # Polynomial bound p(n) = n^2 for simplicity

    return {
        "metric_name": "Rank vs DPLL Size",
        "metric_value": metric_value,
        "instances_tested": 1,
        "conjecture_holds": conjecture_holds,
        "counterexample": "" if conjecture_holds else f"Ratio {metric_value} > n^2 for n={n}"
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [random.randint(100, 999) for _ in range(30)]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")
        results.append(result)

    mean_metric_value = sum(r["metric_value"] for r in results) / len(results)
    std_metric_value = math.sqrt(sum((r["metric_value"] - mean_metric_value)**2 for r in results) / len(results))
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={mean_metric_value} std={std_metric_value} support_fraction={support_fraction}")
    elif support_fraction >= 0.8:
